from io import BytesIO
from jinja2.ext import babel_extract
import babel; print("babel", babel.__version__)

tmpl = b"""<h1>{{ _("Hello") }}</h1>
{# trans: a translator comment #}
{{ gettext("Commented") }}
{% trans %}Block message{% endtrans %}
{% trans count %}{{ count }} apple{% pluralize %}{{ count }} apples{% endtrans %}
{% trans "Ctx" %}Contextual{% endtrans %}
{{ ngettext("one", "many", n) }}
{{ pgettext("Menu", "File") }}
{{ npgettext("Menu", "item", "items", n) }}
{% trans %}
   multi
   line
{% endtrans %}
"""
print("== default")
for r in babel_extract(BytesIO(tmpl), ["_", "gettext", "ngettext", "pgettext", "npgettext"], ["trans:"], {}):
    print("  ", r)
print("== trimmed=true, newstyle_gettext=true")
for r in babel_extract(BytesIO(tmpl), ["_", "gettext", "ngettext", "pgettext", "npgettext"], ["trans:"],
                       {"trimmed": "true", "newstyle_gettext": "true"}):
    print("  ", r)
print("== custom delimiters + extension option")
t2 = b"<% trans %>Custom<% endtrans %><< _('x') >>{% do 1 %}"
for r in babel_extract(BytesIO(t2), ["_", "gettext"], [], {
    "block_start_string": "<%", "block_end_string": "%>",
    "variable_start_string": "<<", "variable_end_string": ">>",
    "extensions": "jinja2.ext.do",
}):
    print("  ", r)
print("== syntax error silent default (True)")
print("  ", list(babel_extract(BytesIO(b"{% for %}"), ["_"], [], {})))
print("== silent=false")
try:
    list(babel_extract(BytesIO(b"{% for %}"), ["_"], [], {"silent": "false"}))
except Exception as ex:
    print("  ", type(ex).__name__, ex)
print("== encoding option")
print("  ", list(babel_extract(BytesIO('{{ _("café") }}'.encode("latin-1")), ["_"], [], {"encoding": "latin-1"})))
print("== line statements/comments")
t3 = b"# trans: hello comment\n# do 1\n{{ _('ls') }}"
print("  ", list(babel_extract(BytesIO(t3), ["_"], ["trans:"], {"line_statement_prefix": "%", "line_comment_prefix": "#"})))

print("== via real babel API (entry point)")
from babel.messages.extract import extract
res = list(extract("jinja2.ext.babel_extract", BytesIO(tmpl),
                   keywords={"_": None, "gettext": None, "ngettext": (1, 2), "pgettext": ((1, "c"), 2), "npgettext": ((1, "c"), 2, 3)},
                   comment_tags=["trans:"], options={}))
for r in res: print("  ", r)
